import{_ as o,Y as i,o as r,c as l,a as s,Z as p,H as a,aA as h}from"./chunks/framework.C6iXY4oq.js";import"./chunks/theme.DxPpgtNj.js";const b=JSON.parse('{"title":"Icon Resources","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/icon-resources.md","filePath":"en/guide/icon-resources.md"}'),c={name:"en/guide/icon-resources.md"};function d(k,e,u,g,E,m){const t=i("IconResources",!0),n=i("NolebaseGitChangelog");return r(),l("div",null,[e[0]||(e[0]=s("h1",{id:"icon-resources",tabindex:"-1"},[p("Icon Resources "),s("a",{class:"header-anchor",href:"#icon-resources","aria-label":'Permalink to "Icon Resources"'},"​")],-1)),e[1]||(e[1]=s("blockquote",null,[s("p",null,"The following are the current community-maintained notification icon resource rules. You can review these rules or go to the contribution section to request adaptations or submit new icon adaptations.")],-1)),a(t),e[2]||(e[2]=h(`<h2 id="trademark-disclaimer" tabindex="-1">Trademark Disclaimer <a class="header-anchor" href="#trademark-disclaimer" aria-label="Permalink to &quot;Trademark Disclaimer&quot;">​</a></h2><p>The product names, logos, and brands displayed in the above resources are the property of their respective owners. All company, product, and service names used in the icon resources are for identification, compatibility, and illustrative purposes only. Use of these names, logos, and brands does not imply endorsement.</p><h2 id="structure-description" tabindex="-1">Structure Description <a class="header-anchor" href="#structure-description" aria-label="Permalink to &quot;Structure Description&quot;">​</a></h2><ul><li><p>The resource rules directory is fixed into the following structure, all located in the project&#39;s <code>icons</code> directory.</p></li><li><p>Third-party app rules are located at <a href="https://github.com/BetterAndroid/android-notification-icon-project/blob/main/icons/app/" target="_blank" rel="noreferrer">icons/app</a></p></li><li><p>Game rules are located at <a href="https://github.com/BetterAndroid/android-notification-icon-project/blob/main/icons/game/" target="_blank" rel="noreferrer">icons/game</a></p></li><li><p>System rules are located at <a href="https://github.com/BetterAndroid/android-notification-icon-project/blob/main/icons/system/" target="_blank" rel="noreferrer">icons/system</a></p></li></ul><p>In each directory, if there are no direct sub-projects, there will be a <code>manifest.json</code> file, and the corresponding registered icon resources are located in the <code>res</code> directory.</p><p>ANIP provides a brand-new rule file structure. Below is a complete example of the rules.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.app&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;label&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Example&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;format&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;svg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;color&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#4F7CF7&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;overlay&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;contributors&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;peter, jane&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>label</code>: The official name of the app, supports i18n</li><li><code>format</code>: The format of the icon file, must match the file extension in the <code>res</code> directory</li><li><code>color</code>: The color used in the icon, format must be uppercase #RRGGBB, no alpha channel allowed</li><li><code>overlay</code>: Whether to force overlay all notification icons pushed by the app, regardless of whether they are native monochrome</li><li><code>contributors</code>: List of contributor names, multiple contributors separated by <code>,</code> (with a space following)</li></ul><p>The <code>label</code>, <code>format</code>, and <code>contributors</code> fields are required.</p><p>The i18n support format for <code>label</code> is as follows, using standard BCP 47 language tags, with <code>-</code> separating the language and region.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;label&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;en&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Example&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;zh-CN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;示例应用&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Similarly, this rule must have a corresponding <code>com.example.app.svg</code> file in the <code>res</code> directory, with the package name as the file name and <code>format</code> as the extension.</p><p>In general, the file name and extension must be in lowercase.</p><p>To address the resource duplication caused by Base64 bloat in older formats and repeated adaptation of icons in channel packages, ANIP provides the <code>target</code> parameter to inherit icon resources from other package names, avoiding repeated resource occupation.</p><p>Below is an example of a rule using the <code>target</code> parameter.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.app.foo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.app&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;label&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Example (Foo)&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>In this example, the icon resource for <code>com.example.app.foo</code> will inherit the icon resource from <code>com.example.app</code>. As long as the <code>target</code> parameter is declared, there is no need for a <code>com.example.app.foo.svg</code> file in the <code>res</code> directory. The other parameters are obtained through inheritance, and you can override them, but note that overriding the <code>format</code> parameter is invalid and will be automatically discarded.</p><p>Want to contribute to icon resources? Please go to <a href="./../contribute/submit">Ready to Submit</a> to participate immediately.</p><h2 id="usage-instruction" tabindex="-1">Usage Instruction <a class="header-anchor" href="#usage-instruction" aria-label="Permalink to &quot;Usage Instruction&quot;">​</a></h2><p>All icon resources of ANIP are free, open, and maintained by contributors. Anyone can use, modify, and distribute the resources of this project in compliance with the Apache-2.0 license. You can check <a href="./../about/adopters">here</a> to see the projects currently using ANIP.</p><p>Each contributed icon will be automatically packaged. The latest icon resources are available in the <a href="https://github.com/BetterAndroid/android-notification-icon-project/releases/" target="_blank" rel="noreferrer">Releases</a> page of the current repository, tagged with the SHA-1 hash of each submission. The file name is similar to <code>anip-bundle-&lt;SHA1&gt;.zip</code>, and the package structure is as follows.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>anip-bundle-&lt;SHA1&gt;.zip</span></span>
<span class="line"><span>├─ app/</span></span>
<span class="line"><span>├─ game/</span></span>
<span class="line"><span>└─ system/</span></span></code></pre></div><p>The same release also provides a release manifest with the fixed name <code>anip-release.json</code>. It describes the current resource bundle and provides integrity verification information in the following structure.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schemaVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tag&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1a2b3c4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;timestamp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1788451200000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;assetName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;anip-bundle-1a2b3c4.zip&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;downloadUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;anip-bundle-1a2b3c4.zip&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;size&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1234567</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sha256&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>schemaVersion</code>: Release manifest schema version, currently fixed at <code>1</code></li><li><code>tag</code>: Current release tag, consisting of the first seven characters of the corresponding main-branch commit SHA-1</li><li><code>timestamp</code>: Unix timestamp of the corresponding commit, in milliseconds</li><li><code>assetName</code>: Full file name of the current icon resource archive</li><li><code>downloadUrl</code>: Download address of the icon resource archive, either an absolute URL or a path relative to the release manifest URL</li><li><code>size</code>: Icon resource archive size in bytes</li><li><code>sha256</code>: SHA-256 checksum of the icon resource archive</li></ul><p>We do not recommend using the project&#39;s resources directly through raw. Instead, pull the latest release package for use, or use the ANIP&#39;s <a href="./../sdk/quick-start">Official SDK</a>.</p>`,26)),a(n)])}const F=o(c,[["render",d]]);export{b as __pageData,F as default};
